INSERT INTO public.faqs (question, answer, category) VALUES
  ('Stiker RFID Toyota Avanza saya gagal scan. Apa yang harus dilakukan?', 'Jika stiker RFID Toyota Avanza Anda mengalami gagal scan, periksa status verifikasinya di menu ''Armada''. Jika masih pending, kunjungi petugas SPBU terdekat untuk verifikasi fisik. Jika rusak fisik, Anda dapat mengajukan penggantian stiker baru lewat stasiun SPBU SFRT terdekat.', 'RFID'),
