INSERT INTO public.faqs (question, answer, category) VALUES
  ('Bisa bayar pengisian Pertamax pakai QRIS bank apa saja?', 'Tentu saja! QRIS SFRT dinamis untuk pengisian Pertamax mendukung pembayaran dari seluruh aplikasi M-Banking (BCA, Mandiri, BRI, BNI) serta E-Wallet populer seperti GoPay, OVO, Dana, LinkAja, dan ShopeePay.', 'PAYMENT'),
  ('Bisa bayar pengisian Pertalite pakai QRIS bank apa saja?', 'Tentu saja! QRIS SFRT dinamis untuk pengisian Pertalite mendukung pembayaran dari seluruh aplikasi M-Banking (BCA, Mandiri, BRI, BNI) serta E-Wallet populer seperti GoPay, OVO, Dana, LinkAja, dan ShopeePay.', 'PAYMENT'),
  ('Bisa bayar pengisian Pertamax Turbo pakai QRIS bank apa saja?', 'Tentu saja! QRIS SFRT dinamis untuk pengisian Pertamax Turbo mendukung pembayaran dari seluruh aplikasi M-Banking (BCA, Mandiri, BRI, BNI) serta E-Wallet populer seperti GoPay, OVO, Dana, LinkAja, dan ShopeePay.', 'PAYMENT'),
